-- ====================================================================
--  Setup IELTS Tests & Remove Writing/Speaking Tests
--  Paste this into your Supabase SQL Editor and click RUN.
-- ====================================================================

-- 1. Remove writing and speaking tests and cascade data
delete from test_sessions where test_id in (
  select distinct t.id
    from tests t
    join sections s on s.test_id = t.id
   where s.kind in ('writing', 'speaking')
);

delete from tests where id in (
  select distinct t.id
    from tests t
    join sections s on s.test_id = t.id
   where s.kind in ('writing', 'speaking')
);

delete from user_progress where kind in ('writing', 'speaking');
delete from ai_analyses where scope in ('writing', 'speaking');

-- 2. Seed and publish IELTS Listening and Reading tests
select seed_test($seed${"external_id":"original-listening-1","title":"IELTS Listening Test 1","is_full_mock":false,"is_published":true,"source_provenance":{"origin":"original","watermark":null,"shippable":true,"repaired_by":null},"sections":[{"external_id":"original-listening-1:s1","kind":"listening","ordinal":1,"duration_seconds":510,"stimulus":{"type":"audio","audio_url":"audio/original-listening-1.mp3","transcript":[{"speaker":null,"text":"Section one. You will hear a telephone conversation between a woman and a member of staff at a community sports centre. First you have some time to look at questions one to ten."},{"speaker":"Woman","text":"Good morning, Fairfield Community Sports Centre, Rosa speaking."},{"speaker":"Man","text":"Oh, hello. I'd like to join the centre, if that's possible over the phone."},{"speaker":"Woman","text":"Of course. I'll take your details. Can I start with your full name?"},{"speaker":"Man","text":"It's Daniel Ashcroft. Ashcroft is spelled A-S-H-C-R-O-F-T."},{"speaker":"Woman","text":"Thank you. And your date of birth?"},{"speaker":"Man","text":"The twelfth of March, nineteen ninety-four."},{"speaker":"Woman","text":"Lovely. What's the best address for us?"},{"speaker":"Man","text":"Forty-two Wilton Road. That's W-I-L-T-O-N."},{"speaker":"Woman","text":"And a contact number?"},{"speaker":"Man","text":"Oh seven double seven, nine oh four, three one six."},{"speaker":"Woman","text":"Perfect. Now, we have three types of membership. There's Standard, which is thirty-two pounds a month, Off-Peak at twenty-four, and Family at fifty-five."},{"speaker":"Man","text":"I only really get here in the mornings, so the Off-Peak one sounds right."},{"speaker":"Woman","text":"That's the sensible choice then. Off-Peak runs until four in the afternoon on weekdays, and all day at weekends."},{"speaker":"Man","text":"That works. What about the pool?"},{"speaker":"Woman","text":"The pool is included, but do note it closes on Tuesdays for maintenance."},{"speaker":"Man","text":"Right, I'll avoid Tuesdays. Do I need to bring anything on my first visit?"},{"speaker":"Woman","text":"Just some photo identification, and we'll take your picture for the card here."},{"speaker":"Man","text":"And is there parking?"},{"speaker":"Woman","text":"There is, but it's for two hours only unless you buy a permit, which is fifteen pounds a year."},{"speaker":"Man","text":"I'll probably walk. One last thing, when does the membership actually start?"},{"speaker":"Woman","text":"We'll activate it on the first of next month, so you get a full month."},{"speaker":"Man","text":"Excellent. Thank you very much."},{"speaker":null,"text":"That is the end of section one. You now have half a minute to check your answers."},{"speaker":null,"text":"Section two. You will hear a talk given to new volunteers at a city botanic garden. First you have some time to look at questions eleven to twenty."},{"speaker":"Speaker","text":"Welcome, everybody, and thank you for giving up your Saturday. I'm Priya, and I coordinate the volunteer programme here at the garden."},{"speaker":"Speaker","text":"A little history first. The garden was founded in eighteen eighty-six by a local textile manufacturer who wanted somewhere for mill workers to walk on a Sunday."},{"speaker":"Speaker","text":"It covers eleven hectares, which makes it the second largest green space in the city after the main park."},{"speaker":"Speaker","text":"We hold around four thousand plant species, and about a fifth of those are grown from seed collected in the wild."},{"speaker":"Speaker","text":"Now, the practical side. Volunteers work in one of four teams. The propagation team works in the glasshouses and needs no previous experience."},{"speaker":"Speaker","text":"The borders team does the heavier planting outdoors, so we do ask for a reasonable level of fitness there."},{"speaker":"Speaker","text":"The third team looks after the herbarium, which is our collection of dried and pressed specimens. That work is indoors and quite detailed."},{"speaker":"Speaker","text":"And the fourth team runs guided walks for visitors, which means a little training in public speaking, provided free by us."},{"speaker":"Speaker","text":"Whichever team you join, please sign in at the wooden hut by the east gate, not at the main reception."},{"speaker":"Speaker","text":"Tools are kept in the shed behind the glasshouses, and the code for the padlock changes every January."},{"speaker":"Speaker","text":"Finally, lunch. There's a staff room above the shop with a kettle and a fridge, and volunteers get a third off anything in the cafe."},{"speaker":null,"text":"That is the end of section two."},{"speaker":null,"text":"Section three. You will hear two students, Mei and Tom, discussing a project with their tutor. First you have some time to look at questions twenty-one to thirty."},{"speaker":"Tutor","text":"Come in, both of you. How's the river study coming along?"},{"speaker":"Woman","text":"Reasonably well. We've finished the sampling, but we're arguing about how to present it."},{"speaker":"Tutor","text":"Arguing is usually a good sign at this stage. What's the disagreement?"},{"speaker":"Man","text":"Mei wants to lead with the water chemistry. I think the invertebrate counts tell the story better."},{"speaker":"Tutor","text":"And why do you think that, Tom?"},{"speaker":"Man","text":"Because the chemistry only shows what the river was like on the day we sampled. The invertebrates reflect months of conditions."},{"speaker":"Tutor","text":"That's a fair point, and it's the standard argument for biological monitoring. Mei, what's your case?"},{"speaker":"Woman","text":"Only that the chemistry is what our reader will expect. But I take Tom's point, and I'd rather be right than conventional."},{"speaker":"Tutor","text":"Then lead with the invertebrates and use the chemistry to support them. What about the sampling itself, did you manage all six sites?"},{"speaker":"Woman","text":"Five. The sixth was inaccessible after the flooding in February."},{"speaker":"Tutor","text":"That's worth stating plainly in your methods rather than hoping nobody counts. Now, your kick-sampling technique, how long did you sample at each site?"},{"speaker":"Man","text":"Three minutes, following the standard protocol."},{"speaker":"Tutor","text":"Good. And did you record the substrate type?"},{"speaker":"Woman","text":"We did, though only as a rough category. Gravel, sand, or silt."},{"speaker":"Tutor","text":"That's enough for this project. What surprised you most?"},{"speaker":"Man","text":"The site downstream of the treatment works was healthier than the one upstream. We expected the opposite."},{"speaker":"Tutor","text":"That happens more often than people assume. What explanation are you offering?"},{"speaker":"Woman","text":"We think it's the shade. The upstream site has no tree cover at all, so it warms up considerably in summer."},{"speaker":"Tutor","text":"Plausible, but you'll need the temperature data to support it. Do you have it?"},{"speaker":"Man","text":"We have spot readings, not continuous logging."},{"speaker":"Tutor","text":"Then present it as a hypothesis rather than a conclusion. When can I see a draft?"},{"speaker":"Woman","text":"We were hoping for the end of next week, if that's not too late."},{"speaker":"Tutor","text":"That's fine. Bring the raw data as well as the write-up."},{"speaker":null,"text":"That is the end of section three."},{"speaker":null,"text":"Section four. You will hear part of a lecture about the history of standardised time. First you have some time to look at questions thirty-one to forty."},{"speaker":"Tutor","text":"Before the railways, every town in Britain kept its own time, set by the sun. Bristol clocks ran about ten minutes behind London, and nobody found this inconvenient."},{"speaker":"Tutor","text":"What changed was not technology but scheduling. A timetable is meaningless if the two ends of the line disagree about when noon is."},{"speaker":"Tutor","text":"The Great Western Railway adopted London time across its network in eighteen forty, and other companies followed within the decade."},{"speaker":"Tutor","text":"For some years the two systems ran side by side. A number of town clocks were fitted with a second minute hand showing railway time."},{"speaker":"Tutor","text":"Resistance was real, and it was mostly legal rather than sentimental. Court cases turned on which time a contract referred to."},{"speaker":"Tutor","text":"The most cited example is a case in eighteen fifty-eight in Dorchester, where a hearing was lost because the judge used local time and the defendant arrived on railway time."},{"speaker":"Tutor","text":"Parliament did not settle the matter until eighteen eighty, when Greenwich Mean Time was given legal force throughout Great Britain."},{"speaker":"Tutor","text":"The international problem was harder, and it was solved by a conference in Washington in eighteen eighty-four, which chose Greenwich as the prime meridian."},{"speaker":"Tutor","text":"The vote was not unanimous. France abstained, and continued to define its own time by reference to Paris for another quarter of a century."},{"speaker":"Tutor","text":"What I want you to take from this is that standardisation is rarely a technical achievement. It is almost always a negotiation, and the winner is usually whoever already runs the network."},{"speaker":null,"text":"That is the end of section four. You now have ten minutes to transfer your answers to the answer sheet."}],"markers":[{"question_ordinal":1,"time_seconds":34.3,"text":"It's Daniel Ashcroft. Ashcroft is spelled A-S-H-C-R-O-F-T."},{"question_ordinal":2,"time_seconds":41.8,"text":"The twelfth of March, nineteen ninety-four."},{"question_ordinal":3,"time_seconds":48.6,"text":"Forty-two Wilton Road. That's W-I-L-T-O-N."},{"question_ordinal":4,"time_seconds":54.6,"text":"Oh seven double seven, nine oh four, three one six."},{"question_ordin