]},{"external_id":"listening-4:s4","kind":"listening","ordinal":4,"duration_seconds":900,"stimulus":{"type":"audio","audio_url":"audio/listening-4.mp3","transcript":[],"markers":[]},"groups":[{"external_id":"listening-4:s4:g1","ordinal":1,"instructions":"Questions 31-40 Complete the notes below. Write ONE WORD ONLY for each answer.","shared_options":null,"questions":[{"external_id":"listening-4:q31","ordinal":31,"type":"note_completion","prompt":"Local fish farmers are afraid that genetically modified fish will ____ into the sea.","options":null,"correct_answer":"escape","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q32","ordinal":32,"type":"note_completion","prompt":"• like to breed fish with special features, like ____","options":null,"correct_answer":"tuna","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q33","ordinal":33,"type":"note_completion","prompt":"– to build some cages to prevent the fish from ____","options":null,"correct_answer":"storms","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q34","ordinal":34,"type":"note_completion","prompt":"– to use ____ nets to support the frames of the cages","options":null,"correct_answer":"strong","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q35","ordinal":35,"type":"note_completion","prompt":"• lack of land on the ____","options":null,"correct_answer":"coast","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q36","ordinal":36,"type":"note_completion","prompt":"• lack of ____ fish","options":null,"correct_answer":"young","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q37","ordinal":37,"type":"note_completion","prompt":"• encourages fish farmers to ____ local fish farming business","options":null,"correct_answer":"support","accepted_variants":[],"evidence":null},{"external_id":"listening-4:q38","ordinal":38,"type":"note_completion","prompt":"– Seaweed can be used to make ____","options":null,"corre